function InstrumentsUpd(Song: music.Playable[], SongName: string) {
    PlaySong = customInstruments.makeSongWritable(Song[0])
    if (SongName == "Burning_Fury") {
        customInstruments.setWaveform(PlaySong, customInstruments.InstrumentId.Dog, customInstruments.Waveform.Pulse20)
        customInstruments.setOctave(PlaySong, customInstruments.InstrumentId.Dog, 2)
        customInstruments.setWaveform(PlaySong, customInstruments.InstrumentId.Computer, customInstruments.Waveform.Sawtooth)
        customInstruments.setOctave(PlaySong, customInstruments.InstrumentId.Computer, 1)
    }
    if (SongName == "Overthrone") {
        customInstruments.setWaveform(PlaySong, customInstruments.InstrumentId.Lemon, customInstruments.Waveform.Square)
        customInstruments.setOctave(PlaySong, customInstruments.InstrumentId.Lemon, 2)
        customInstruments.setWaveform(PlaySong, customInstruments.InstrumentId.Computer, customInstruments.Waveform.Pulse10)
        customInstruments.setOctave(PlaySong, customInstruments.InstrumentId.Computer, 2)
    }
    music.play(PlaySong, music.PlaybackMode.UntilDone)
}

